import json, os
from datetime import datetime

dir_path = '/tmp/ytdl/'
all_videos = []

for fname in sorted(os.listdir(dir_path)):
    if not fname.endswith('.json'):
        continue
    try:
        with open(os.path.join(dir_path, fname)) as f:
            d = json.load(f)
            all_videos.append(d)
    except:
        pass

print(f"Total videos: {len(all_videos)}")

# Filter by date range and duration
start = datetime(2024, 1, 1)
end = datetime(2025, 7, 1)

filtered = []
for v in all_videos:
    upload_date_str = v.get('upload_date', 'NA')
    if upload_date_str == 'NA':
        continue
    try:
        upload_date = datetime.strptime(upload_date_str, '%Y%m%d')
    except:
        continue
    duration = v.get('duration', 0)
    if duration is None:
        duration = 0
    if upload_date >= start and upload_date <= end and duration > 120:
        filtered.append({
            'id': v.get('id', ''),
            'title': v.get('title', ''),
            'upload_date': upload_date_str,
            'duration': duration
        })

# Sort by upload date
filtered.sort(key=lambda x: x['upload_date'])

print(f"Filtered videos ({len(filtered)}):")
for v in filtered:
    print(f"  {v['upload_date']}: {v['id']} - {v['title'][:60]} ({v['duration']}s)")
PYEOF
